INSERT INTO problem_versions (id, problem_id, version_no, status, statement_md, constraints_md, java_template, published_at) VALUES
 (2201, 1201, 1, 'PUBLISHED', '给定一个整数数组 `nums` 和一个整数 `val`，请原地移除所有数值等于 `val` 的元素，并返回移除后数组中剩余元素的个数。\n输入格式：一行，数组 `nums` 与整数 `val`，两者之间用单个 `;` 分隔；数组写成 `[3,2,2,3]` 形式（元素之间无空格），例如 `[3,2,2,3];3`。\n输出格式：一行，一个十进制整数，表示移除 `val` 后数组中剩余元素的个数。', '- `0 <= nums.length <= 1000`\n- `-10^4 <= nums[i] <= 10^4`\n- `-10^4 <= val <= 10^4`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2202, 1202, 1, 'PUBLISHED', '给定一个按非递减顺序排列的整数数组 `nums`，请原地删除重复出现的元素，使每个元素只出现一次，并返回删除后数组的新长度 `k`。\n输入格式：一行，一个数组 `nums`，写成 `[1,1,2]` 形式（元素之间无空格）。\n输出格式：一行，一个十进制整数，表示去重后数组中元素的个数 `k`。', '- `1 <= nums.length <= 10^5`\n- `-10^4 <= nums[i] <= 10^4`\n- `nums` 按非递减顺序排列', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2203, 1203, 1, 'PUBLISHED', '给定一个按非递减顺序排列的整数数组 `nums`，返回每个元素的平方组成的新数组，要求新数组同样按非递减顺序排列。\n输入格式：一行，一个数组 `nums`，写成 `[-4,-1,0,3,10]` 形式（元素之间无空格）。\n输出格式：一行，平方后按非递减顺序排列的数组，写成 `[0,1,9]` 形式（元素之间无空格）。', '- `1 <= nums.length <= 10^4`\n- `-10^4 <= nums[i] <= 10^4`\n- `nums` 按非递减顺序排列', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2204, 1204, 1, 'PUBLISHED', '给定一个整数数组 `nums`，返回它的动态和数组 `runningSum`，其中 `runningSum[i]` 等于 `nums[0]` 到 `nums[i]` 所有元素之和。\n输入格式：一行，一个数组 `nums`，写成 `[1,2,3,4]` 形式（元素之间无空格）。\n输出格式：一行，前缀和数组，写成 `[1,3,6,10]` 形式（元素之间无空格）。', '- `0 <= nums.length <= 1000`\n- `-10^6 <= nums[i] <= 10^6`\n- 任意前缀和的绝对值不超过 `10^9`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2205, 1205, 1, 'PUBLISHED', '给定一个整数数组 `nums`，请找出最左侧的「中心下标」：该下标左侧所有元素之和等于右侧所有元素之和。若中心下标位于数组最左端，则左侧和为 0；位于最右端则右侧和为 0。\n输入格式：一行，一个数组 `nums`，写成 `[1,7,3,6,5,6]` 形式（元素之间无空格）。\n输出格式：一行，一个十进制整数，表示最左侧的中心下标；若不存在这样的下标，输出 `-1`。', '- `1 <= nums.length <= 10^4`\n- `-1000 <= nums[i] <= 1000`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2206, 1206, 1, 'PUBLISHED', '给定一个字符串，请将它反转后输出。\n输入格式：一行，一个不含空格与换行符的字符串，直接写出内容，例如 `hello`。\n输出格式：一行，反转后的字符串，不加引号。', '- `1 <= s.length <= 10^5`\n- `s` 只由可见字符组成，且不含空格', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2207, 1207, 1, 'PUBLISHED', '给定一个整数数组 `nums`，请将所有偶数移动到数组前面、所有奇数移动到数组后面，并保持偶数之间、奇数之间原有的相对顺序不变。\n输入格式：一行，一个数组 `nums`，写成 `[3,1,2,4]` 形式（元素之间无空格）。\n输出格式：一行，调整后的数组，写成 `[2,4,3,1]` 形式（元素之间无空格）。', '- `0 <= nums.length <= 10^4`\n- `-10^4 <= nums[i] <= 10^4`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2208, 1208, 1, 'PUBLISHED', '给定一个固定长度的整数数组 `nums`，请将其中每个 `0` 再复写一遍，并把原来位于其后的元素向右平移一位。超出数组长度的元素直接丢弃，最终数组长度保持不变。\n输入格式：一行，一个数组 `nums`，写成 `[1,0,2,3,0,4,5,2]` 形式（元素之间无空格）。\n输出格式：一行，修改后的数组，写成 `[1,0,0,2,3,0,0,4]` 形式（元素之间无空格）。', '- `1 <= nums.length <= 10^4`\n- `0 <= nums[i] <= 10^4`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2209, 1209, 1, 'PUBLISHED', '给定一个整数数组 `nums`，请将数组中的元素向右轮转 `k` 个位置。\n输入格式：一行，数组 `nums` 与整数 `k`，两者之间用单个 `;` 分隔；数组写成 `[1,2,3,4,5,6,7]` 形式（元素之间无空格），例如 `[1,2,3,4,5,6,7];3`。\n输出格式：一行，轮转后的数组，写成 `[5,6,7,1,2,3,4]` 形式（元素之间无空格）。', '- `1 <= nums.length <= 10^5`\n- `-10^4 <= nums[i] <= 10^4`\n- `0 <= k <= 10^5`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2210, 1210, 1, 'PUBLISHED', '给定一个长度为 `n` 的整数数组 `height`，第 `i` 条垂线的两个端点分别是 `(i, 0)` 和 `(i, height[i])`。请找出其中的两条垂线，使它们与 x 轴共同围成的容器能容纳最多的水，返回该容器的最大容量。\n输入格式：一行，一个数组 `height`，写成 `[1,8,6,2,5,4,8,3,7]` 形式（元素之间无空格）。\n输出格式：一行，一个十进制整数，表示容器的最大容量。', '- `2 <= height.length <= 10^5`\n- `0 <= height[i] <= 10^4`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2211, 1211, 1, 'PUBLISHED', '给定一个整数数组 `nums` 和一个整数 `k`，请统计并返回数组中元素之和恰好等于 `k` 的连续子数组的个数。\n输入格式：一行，数组 `nums` 与整数 `k`，两者之间用单个 `;` 分隔；数组写成 `[1,1,1]` 形式（元素之间无空格），例如 `[1,1,1];2`。\n输出格式：一行，一个十进制整数，表示和为 `k` 的连续子数组个数。', '- `1 <= nums.length <= 2 * 10^4`\n- `-1000 <= nums[i] <= 1000`\n- `-10^7 <= k <= 10^7`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2212, 1212, 1, 'PUBLISHED', '给定一个只包含 `0`、`1`、`2` 的整数数组 `nums`，请原地将它们按 `0`、`1`、`2` 的顺序排列，并输出排列后的数组。\n输入格式：一行，一个数组 `nums`，写成 `[2,0,2,1,1,0]` 形式（元素之间无空格）。\n输出格式：一行，升序排列后的数组，写成 `[0,0,1,1,2,2]` 形式（元素之间无空格）。', '- `1 <= nums.length <= 10^5`\n- `nums[i]` 只能是 `0`、`1` 或 `2`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2213, 1213, 1, 'PUBLISHED', '给定一个合法的算术表达式字符串 `s`，求出其中括号的最大嵌套深度。某个位置处的深度，等于该位置之前尚未闭合的左括号数量。\n输入格式：一行，字符串 `s`，不带引号，只含数字、`+`、`-`、`*`、`/`、`(` 和 `)`，保证括号配对合法。\n输出格式：一行，一个十进制整数，表示表达式中括号的最大嵌套深度；若表达式中不含括号，输出 `0`。', '- `1 <= s.length <= 10^4`\n- `s` 只含数字、`+`、`-`、`*`、`/`、`(` 和 `)`\n- 括号配对合法，表达式非空', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2214, 1214, 1, 'PUBLISHED', '给定一个字符串 `s`，先忽略它的大小写，并只保留其中的英文字母和数字，再判断得到的字符串从左到右读与从右到左读是否完全一致；空字符串视为回文串。\n输入格式：一行，字符串 `s`，不带引号，可能包含英文字母、数字、空格和标点符号，行首与行尾没有空格（也可能整行为空）。\n输出格式：一行，若处理后是回文串输出 `true`，否则输出 `false`，均为小写。', '- `0 <= s.length <= 2 * 10^5`\n- `s` 只含可打印 ASCII 字符\n- `s` 的行首与行尾没有空格', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2215, 1215, 1, 'PUBLISHED', '给定一个只含小写英文字母的字符串 `s`。反复执行以下操作：找出字符串中相邻且相同的两个字符并删除它们；直到不存在这样的相邻重复字符为止。输出最终剩下的字符串。\n输入格式：一行，字符串 `s`，不带引号，只含小写英文字母。\n输出格式：一行，删除所有相邻重复项后剩下的字符串，直接打印内容，不加引号。', '- `1 <= s.length <= 10^5`\n- `s` 只含小写英文字母', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2216, 1216, 1, 'PUBLISHED', '记录一场棒球比赛的得分。输入是一串用 `,` 分隔的操作，每个操作的含义如下：\n- 一个十进制整数 `x`：本回合得到 `x` 分；\n- `+`：本回合得分为前两回合得分之和；\n- `D`：本回合得分为前一回合得分的两倍；\n- `C`：前一回合得分无效，把它从记录中移除。\n所有操作处理完毕后，输出所有有效回合得分之和。\n输入格式：一行，操作序列，操作之间用 `,` 分隔，例如 `5,2,C,D,+`。\n输出格式：一行，一个十进制整数，表示所有有效回合得分之和。', '- `1 <= 操作数 <= 10^4`\n- 保证每个操作都有足够的已有回合记录（`+` 至少有两个，`D` 与 `C` 至少有一个）\n- 所有回合得分与总分都在 32 位有符号整数范围内', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2217, 1217, 1, 'PUBLISHED', '按时间先后依次接收若干请求。每当收到一个新请求的时刻 `t` 时，统计闭区间 `[t - 3000, t]` 内收到的请求数量（包含当前这次请求）。\n输入格式：一行，若干整数，表示按递增顺序到来的请求时刻，整数之间用 `,` 分隔，例如 `1,100,3001,3002`。\n输出格式：一行，对每个请求依次输出它的统计数量，数字之间用 `,` 分隔。', '- `1 <= 请求数 <= 10^4`\n- `1 <= t <= 10^9`\n- 请求时刻严格递增', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
